CREATE TABLE public.cta_clicks (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, source TEXT NOT NULL, lang TEXT NOT NULL DEFAULT 'en', referrer TEXT, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()); GRANT INSERT ON public.cta_clicks TO service_role; GRANT ALL ON public.cta_clicks TO service_role; ALTER TABLE public.cta_clicks ENABLE ROW LEVEL SECURITY; CREATE INDEX cta_clicks_created_at_idx ON public.cta_clicks (created_at);